import os, re

def load_grids():
    d = os.environ.get('RLM_SESSION_DIR', '')
    base = os.path.basename(d)
    session_file = os.path.join(os.path.dirname(d), f'{base}.jsonl')

    G = {}
    if os.path.exists(session_file):
        text = open(session_file).read()
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', text):
            k, h, w = m[1], int(m[2]), int(m[3])
            rows = [r.split() for r in text[m.end():].split('\n')[:h]]
            if k not in G and len(rows) == h and all(len(r) == w for r in rows):
                G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load_grids()
print("Keys:", sorted(G.keys()))
for k in sorted(G):
    print(f"\n=== {k} ===")
    for i, row in enumerate(G[k]):
        print(row)

